/**
 * DevelopRenderer — top-level renderer for "develop" workflows.
 *
 * Composes the horizontal ProgressIndicator (phase bar) with an AgentGrid
 * showing per-agent log panels.  A small label in .develop-content shows
 * the current (active) phase name.
 */

import type { WorkflowRendererProps } from '../types';
import { registerRenderer } from '../registry';
import { buildDevelopState } from './types';
import { ProgressIndicator } from './ProgressIndicator';
import { AgentGrid } from './AgentGrid';
import './DevelopRenderer.css';

export function DevelopRenderer({ runState }: WorkflowRendererProps) {
  const state = buildDevelopState(runState);

  return (
    <div className="develop-renderer">
      <ProgressIndicator phases={state.phases} />
      <div className="develop-content">
        {state.currentPhase && (
          <div className="develop-phase-label">{state.currentPhase}</div>
        )}
        <AgentGrid agents={state.agents} />
      </div>
    </div>
  );
}

registerRenderer('develop', DevelopRenderer);

.develop-renderer {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

.develop-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: var(--engin-space-sm);
  gap: var(--engin-space-sm);
}

.develop-phase-label {
  font-size: 12px;
  color: var(--engin-text-muted);
  padding: 0 var(--engin-space-sm);
  font-family: var(--engin-font-mono);
  flex-shrink: 0;
}

import type { LogEntry, WorkflowRunState } from '../../types';

// ─── Develop renderer types ─────────────────────────────────────────────────

export interface DevelopPhaseInfo {
  id: string;
  label: string;
  icon: string;
  status: 'completed' | 'active' | 'pending';
}

export interface DevelopAgentInfo {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface DevelopRendererState {
  phases: DevelopPhaseInfo[];
  agents: DevelopAgentInfo[];
  currentPhase: string;
}

// ─── Helper ─────────────────────────────────────────────────────────────────

export function buildDevelopState(runState: WorkflowRunState): DevelopRendererState {
  const phases: DevelopPhaseInfo[] = [];
  const sidebarPhases = runState.summary.sidebar.phases;
  if (sidebarPhases) {
    for (const phase of sidebarPhases) {
      let status: 'completed' | 'active' | 'pending';
      if (runState.completedPhases.includes(phase.id)) {
        status = 'completed';
      } else if (phase.id === runState.currentPhase) {
        status = 'active';
      } else {
        status = 'pending';
      }
      phases.push({
        id: phase.id,
        label: phase.label,
        icon: phase.icon,
        status,
      });
    }
  }

  const agents: DevelopAgentInfo[] = [];
  for (const [agentId, agent] of runState.agents) {
    agents.push({
      agentId: agent.agentId,
      profile: agent.profile,
      taskId: agent.taskId,
      active: agent.active,
      log: agent.log,
    });
  }
  agents.sort((a, b) => a.agentId.localeCompare(b.agentId));

  return {
    phases,
    agents,
    currentPhase: runState.currentPhase,
  };
}

import type { WorkflowRunState } from '../types';

export interface WorkflowRendererProps {
  runState: WorkflowRunState;
}

import type { ComponentType } from 'react';
import type { WorkflowRendererProps } from './types';

const registry = new Map<string, ComponentType<WorkflowRendererProps>>();

export function registerRenderer(
  name: string,
  comp: ComponentType<WorkflowRendererProps>,
): void {
  registry.set(name, comp);
}

export function getRenderer(
  name: string,
): ComponentType<WorkflowRendererProps> | undefined {
  return registry.get(name);
}

import './ProgressIndicator.css';
import type { DevelopPhaseInfo } from './types';

interface ProgressIndicatorProps {
  phases: DevelopPhaseInfo[];
}

export function ProgressIndicator({ phases }: ProgressIndicatorProps) {
  return (
    <div className="progress-indicator">
      {phases.map((phase, index) => (
        <div key={phase.id} className={`phase-item ${phase.status}`}>
          <span className="phase-icon">
            {phase.status === 'completed' ? '✅' : phase.icon}
          </span>
          <span className="phase-label">{phase.label}</span>
          {index < phases.length - 1 && (
            <div
              className={`phase-connector ${phase.status === 'completed' ? 'completed' : 'pending'}`}
            />
          )}
        </div>
      ))}
    </div>
  );
}

/**
 * AgentGrid component.
 *
 * Renders a CSS Grid of agent log panels. Each cell shows an AgentLog
 * with a header containing the agent's profile name and an active/inactive
 * status dot. When there are no agents a centered empty-state message is
 * displayed.
 */

import './AgentGrid.css';
import type { DevelopAgentInfo } from './types';
import { AgentLog } from './AgentLog';

interface AgentGridProps {
  agents: DevelopAgentInfo[];
}

export function AgentGrid({ agents }: AgentGridProps) {
  if (agents.length === 0) {
    return (
      <div className="agent-grid-empty">
        No active agents
      </div>
    );
  }

  return (
    <div className="agent-grid">
      {agents.map((agent) => (
        <div key={agent.agentId} className="agent-cell">
          <div className="agent-cell-header">
            <span className="agent-cell-header-name">
              <span
                className={`agent-cell-status-dot agent-cell-status-dot--${agent.active ? 'active' : 'inactive'}`}
              />
              {agent.profile}
            </span>
          </div>
          <div className="agent-cell-body">
            <AgentLog entries={agent.log} />
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Tests for ProgressIndicator component.
 *
 * Verifies that the horizontal phase bar renders phases with correct
 * styling based on status (completed / active / pending) and that
 * connector lines appear between phases with appropriate color.
 */

import '@testing-library/jest-dom/vitest';

import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';

import { ProgressIndicator } from '../ProgressIndicator';
import type { DevelopPhaseInfo } from '../types';

// ─── Helpers ────────────────────────────────────────────────────────────────

function createPhase(
  overrides: Partial<DevelopPhaseInfo> = {},
): DevelopPhaseInfo {
  return {
    id: 'phase-1',
    label: 'Phase 1',
    icon: '📋',
    status: 'pending',
    ...overrides,
  };
}

// ─── Tests ──────────────────────────────────────────────────────────────────

describe('ProgressIndicator', () => {
  describe('rendering phases', () => {
    it('renders each phase label', () => {
      const phases = [
        createPhase({ id: 'a', label: 'Alpha' }),
        createPhase({ id: 'b', label: 'Beta' }),
        createPhase({ id: 'c', label: 'Gamma' }),
      ];
      render(<ProgressIndicator phases={phases} />);
      expect(screen.getByText('Alpha')).toBeInTheDocument();
      expect(screen.getByText('Beta')).toBeInTheDocument();
      expect(screen.getByText('Gamma')).toBeInTheDocument();
    });

    it('renders phase icons for non-completed phases', () => {
      const phases = [
        createPhase({ id: 'a', icon: '🔍', status: 'active' }),
        createPhase({ id: 'b', icon: '⚙️', status: 'pending' }),
      ];
      render(<ProgressIndicator phases={phases} />);
      expect(screen.getByText('🔍')).toBeInTheDocument();
      expect(screen.getByText('⚙️')).toBeInTheDocument();
    });

    it('shows a checkmark (✅) for completed phases instead of the original icon', () => {
      const phases = [
        createPhase({ id: 'a', icon: '📋', status: 'completed' }),
      ];
      render(<ProgressIndicator phases={phases} />);
      expect(screen.getByText('✅')).toBeInTheDocument();
      expect(screen.queryByText('📋')).not.toBeInTheDocument();
    });

    it('renders nothing when phases array is empty', () => {
      const { container } = render(<ProgressIndicator phases={[]} />);
      const indicator = container.querySelector('.progress-indicator');
      expect(indicator).toBeInTheDocument();
      expect(indicator?.children.length).toBe(0);
    });

    it('renders the correct number of phase items', () => {
      const phases = [
        createPhase({ id: 'a' }),
        createPhase({ id: 'b' }),
        createPhase({ id: 'c' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const items = container.querySelectorAll('.phase-item');
      expect(items).toHaveLength(3);
    });
  });

  describe('status styling', () => {
    it('applies "completed" class for completed phases', () => {
      const phases = [createPhase({ status: 'completed' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item');
      expect(item).toHaveClass('completed');
      expect(item).not.toHaveClass('active');
      expect(item).not.toHaveClass('pending');
    });

    it('applies "active" class for active phases', () => {
      const phases = [createPhase({ status: 'active' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item');
      expect(item).toHaveClass('active');
      expect(item).not.toHaveClass('completed');
      expect(item).not.toHaveClass('pending');
    });

    it('applies "pending" class for pending phases', () => {
      const phases = [createPhase({ status: 'pending' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item');
      expect(item).toHaveClass('pending');
      expect(item).not.toHaveClass('completed');
      expect(item).not.toHaveClass('active');
    });
  });

  describe('connectors', () => {
    it('renders a connector between each pair of phases', () => {
      const phases = [
        createPhase({ id: 'a' }),
        createPhase({ id: 'b' }),
        createPhase({ id: 'c' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connectors = container.querySelectorAll('.phase-connector');
      expect(connectors).toHaveLength(2); // 3 phases → 2 connectors
    });

    it('does not render a connector after the last phase', () => {
      const phases = [
        createPhase({ id: 'a' }),
        createPhase({ id: 'b' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const lastItem = container.querySelector('.phase-item:last-child');
      expect(lastItem?.querySelector('.phase-connector')).toBeNull();
    });

    it('renders no connectors when there is only one phase', () => {
      const phases = [createPhase({ id: 'a' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connectors = container.querySelectorAll('.phase-connector');
      expect(connectors).toHaveLength(0);
    });

    it('applies "completed" class to connector after a completed phase', () => {
      const phases = [
        createPhase({ id: 'a', status: 'completed' }),
        createPhase({ id: 'b', status: 'active' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connector = container.querySelector('.phase-connector');
      expect(connector).toHaveClass('completed');
    });

    it('applies "pending" class to connector after a non-completed (active) phase', () => {
      const phases = [
        createPhase({ id: 'a', status: 'active' }),
        createPhase({ id: 'b', status: 'pending' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connector = container.querySelector('.phase-connector');
      expect(connector).toHaveClass('pending');
    });

    it('applies "pending" class to connector after a pending phase', () => {
      const phases = [
        createPhase({ id: 'a', status: 'pending' }),
        createPhase({ id: 'b', status: 'pending' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connector = container.querySelector('.phase-connector');
      expect(connector).toHaveClass('pending');
    });

    it('uses green connector after completed, gray after non-completed in mixed sequence', () => {
      const phases = [
        createPhase({ id: 'a', status: 'completed' }),
        createPhase({ id: 'b', status: 'completed' }),
        createPhase({ id: 'c', status: 'active' }),
        createPhase({ id: 'd', status: 'pending' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connectors = container.querySelectorAll('.phase-connector');
      expect(connectors).toHaveLength(3);
      // After phase 0 (completed) → completed
      expect(connectors[0]).toHaveClass('completed');
      // After phase 1 (completed) → completed
      expect(connectors[1]).toHaveClass('completed');
      // After phase 2 (active) → pending
      expect(connectors[2]).toHaveClass('pending');
    });
  });

  describe('container and structure', () => {
    it('renders a root element with class "progress-indicator"', () => {
      const { container } = render(<ProgressIndicator phases={[]} />);
      expect(container.querySelector('.progress-indicator')).toBeInTheDocument();
    });

    it('renders phase items inside the progress-indicator', () => {
      const phases = [createPhase({ id: 'a' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const indicator = container.querySelector('.progress-indicator');
      const item = indicator?.querySelector('.phase-item');
      expect(item).toBeInTheDocument();
    });

    it('orders phase items in the same order as the phases prop', () => {
      const phases = [
        createPhase({ id: 'first', label: 'First' }),
        createPhase({ id: 'second', label: 'Second' }),
        createPhase({ id: 'third', label: 'Third' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const items = container.querySelectorAll('.phase-item');
      expect(items[0]).toHaveTextContent('First');
      expect(items[1]).toHaveTextContent('Second');
      expect(items[2]).toHaveTextContent('Third');
    });

    it('each phase-item contains a phase-icon and a phase-label', () => {
      const phases = [createPhase({ id: 'a', icon: '🔍', label: 'Search' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item')!;
      expect(item.querySelector('.phase-icon')).toBeInTheDocument();
      expect(item.querySelector('.phase-label')).toBeInTheDocument();
    });
  });
});

/**
 * Tests for AgentGrid component.
 *
 * Verifies that the grid renders agent cells with profile names, status
 * dots, and AgentLog bodies.  Also verifies the empty state when no
 * agents are provided.
 */

import '@testing-library/jest-dom/vitest';

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';

import { AgentGrid } from '../AgentGrid';
import type { DevelopAgentInfo } from '../types';
import type { LogEntry } from '../../../types';

// ─── Mock @tanstack/react-virtual ──────────────────────────────────────────
// AgentLog uses a virtualizer internally; mock it so that log entries
// appear as rendered content in tests.

const mockScrollToIndex = vi.fn();
const mockGetTotalSize = vi.fn(() => 0);
const mockGetVirtualItems = vi.fn(() => []);

vi.mock('@tanstack/react-virtual', () => ({
  useVirtualizer: vi.fn(() => ({
    getVirtualItems: mockGetVirtualItems,
    getTotalSize: mockGetTotalSize,
    scrollToIndex: mockScrollToIndex,
  })),
}));

// ─── Helpers ────────────────────────────────────────────────────────────────

function createLogEntry(overrides: Partial<LogEntry> = {}): LogEntry {
  return {
    id: 'log-1',
    timestamp: '2024-01-01T00:00:00Z',
    type: 'text',
    content: 'Hello',
    ...overrides,
  };
}

function createAgent(overrides: Partial<DevelopAgentInfo> = {}): DevelopAgentInfo {
  return {
    agentId: 'agent-1',
    profile: 'Default Agent',
    active: true,
    log: [],
    ...overrides,
  };
}

// ─── Tests ──────────────────────────────────────────────────────────────────

describe('AgentGrid', () => {
  describe('empty state', () => {
    it('renders a "No active agents" message when agents array is empty', () => {
      render(<AgentGrid agents={[]} />);
      expect(screen.getByText('No active agents')).toBeInTheDocument();
    });

    it('does not render the grid container when there are no agents', () => {
      const { container } = render(<AgentGrid agents={[]} />);
      expect(container.querySelector('.agent-grid')).toBeNull();
    });

    it('renders the empty state with class "agent-grid-empty"', () => {
      const { container } = render(<AgentGrid agents={[]} />);
      expect(container.querySelector('.agent-grid-empty')).toBeInTheDocument();
    });
  });

  describe('grid rendering', () => {
    it('renders a root element with class "agent-grid"', () => {
      const agents = [createAgent()];
      const { container } = render(<AgentGrid agents={agents} />);
      expect(container.querySelector('.agent-grid')).toBeInTheDocument();
    });

    it('renders one agent-cell per agent', () => {
      const agents = [
        createAgent({ agentId: 'a' }),
        createAgent({ agentId: 'b' }),
        createAgent({ agentId: 'c' }),
      ];
      const { container } = render(<AgentGrid agents={agents} />);
      const cells = container.querySelectorAll('.agent-cell');
      expect(cells).toHaveLength(3);
    });

    it('renders no agent-cells when agents array is empty', () => {
      const { container } = render(<AgentGrid agents={[]} />);
      const cells = container.querySelectorAll('.agent-cell');
      expect(cells).toHaveLength(0);
    });
  });

  describe('agent-cell-header', () => {
    it('renders the profile name inside the header', () => {
      const agents = [createAgent({ profile: 'Alice' })];
      render(<AgentGrid agents={agents} />);
      expect(screen.getByText('Alice')).toBeInTheDocument();
    });

    it('renders profile names for all agents', () => {
      const agents = [
        createAgent({ agentId: 'a', profile: 'Alpha' }),
        createAgent({ agentId: 'b', profile: 'Beta' }),
      ];
      render(<AgentGrid agents={agents} />);
      expect(screen.getByText('Alpha')).toBeInTheDocument();
      expect(screen.getByText('Beta')).toBeInTheDocument();
    });

    it('renders a status dot for each agent', () => {
      const agents = [createAgent({ agentId: 'a' })];
      const { container } = render(<AgentGrid agents={agents} />);
      const header = container.querySelector('.agent-cell-header')!;
      const dot = header.querySelector('.agent-cell-status-dot');
      expect(dot).toBeInTheDocument();
    });

    it('applies active class to status dot when agent is active', () => {
      const agents = [createAgent({ active: true })];
      const { container } = render(<AgentGrid agents={agents} />);
      const dot = container.querySelector('.agent-cell-status-dot');
      expect(dot).toHaveClass('agent-cell-status-dot--active');
      expect(dot).not.toHaveClass('agent-cell-status-dot--inactive');
    });

    it('applies inactive class to status dot when agent is inactive', () => {
      const agents = [createAgent({ active: false })];
      const { container } = render(<AgentGrid agents={agents} />);
      const dot = container.querySelector('.agent-cell-status-dot');
      expect(dot).toHaveClass('agent-cell-status-dot--inactive');
      expect(dot).not.toHaveClass('agent-cell-status-dot--active');
    });

    it('renders status dot before the profile name', () => {
      const agents = [createAgent({ profile: 'Bob' })];
      const { container } = render(<AgentGrid agents={agents} />);
      const header = container.querySelector('.agent-cell-header')!;
      const nameSpan = header.querySelector('.agent-cell-header-name')!;
      const dot = nameSpan.querySelector('.agent-cell-status-dot');
      const text = nameSpan.textContent;
      // dot should be before the profile name in the DOM
      expect(dot).toBeInTheDocument();
      expect(text).toContain('Bob');
    });

    it('renders mixed active and inactive status dots correctly', () => {
      const agents = [
        createAgent({ agentId: 'active-one', active: true }),
        createAgent({ agentId: 'inactive-one', active: false }),
        createAgent({ agentId: 'active-two', active: true }),
      ];
      const { container } = render(<AgentGrid agents={agents} />);
      const dots = container.querySelectorAll('.agent-cell-status-dot');
      expect(dots).toHaveLength(3);
      expect(dots[0]).toHaveClass('agent-cell-status-dot--active');
      expect(dots[1]).toHaveClass('agent-cell-status-dot--inactive');
      expect(dots[2]).toHaveClass('agent-cell-status-dot--active');
    });
  });

  describe('agent-cell-body and AgentLog', () => {
    beforeEach(() => {
      mockGetVirtualItems.mockClear();
      mockGetTotalSize.mockClear();
      mockScrollToIndex.mockClear();
    });

    it('renders a body container inside each cell', () => {
      const agents = [createAgent()];
      const { container } = render(<AgentGrid agents={agents} />);
      const cell = container.querySelector('.agent-cell')!;
      expect(cell.querySelector('.agent-cell-body')).toBeInTheDocument();
    });

    it('renders an AgentLog inside each cell body', () => {
      const agents = [createAgent()];
      const { container } = render(<AgentGrid agents={agents} />);
      const body = container.querySelector('.agent-cell-body')!;
      expect(body.querySelector('.agent-log')).toBeInTheDocument();
    });

    it('passes log entries to AgentLog and renders them', () => {
      const entries = [
        createLogEntry({ id: 'e1', content: 'First entry' }),
        createLogEntry({ id: 'e2', content: 'Second entry' }),
      ];
      // Stub virtualizer to return items for the two entries
      mockGetTotalSize.mockReturnValueOnce(120);
      mockGetVirtualItems.mockReturnValueOnce([
        { key: '0', index: 0, start: 0, size: 60 },
        { key: '1', index: 1, start: 60, size: 60 },
      ] as any);

      const agents = [createAgent({ log: entries })];
      render(<AgentGrid agents={agents} />);
      expect(screen.getByText('First entry')).toBeInTheDocument();
      expect(screen.getByText('Second entry')).toBeInTheDocument();
    });

    it('renders log entries for multiple agents independently', () => {
      const agents = [
        createAgent({ agentId: 'a', log: [createLogEntry({ id: 'a1', content: 'Agent A log' })] }),
        createAgent({ agentId: 'b', log: [createLogEntry({ id: 'b1', content: 'Agent B log' })] }),
      ];
      // Stub virtualizer: each AgentLog instance gets its own mock calls.
      // The mock is called twice (once per AgentLog), so we set up two return values.
      mockGetTotalSize
        .mockReturnValueOnce(60)
        .mockReturnValueOnce(60);
      mockGetVirtualItems
        .mockReturnValueOnce([{ key: '0', index: 0, start: 0, size: 60 }] as any)
        .mockReturnValueOnce([{ key: '0', index: 0, start: 0, size: 60 }] as any);

      render(<AgentGrid agents={agents} />);
      expect(screen.getByText('Agent A log')).toBeInTheDocument();
      expect(screen.getByText('Agent B log')).toBeInTheDocument();
    });

    it('renders empty AgentLog when agent has no log entries', () => {
      const agents = [createAgent({ log: [] })];
      const { container } = render(<AgentGrid agents={agents} />);
      const log = container.querySelector('.agent-log')!;
      expect(log).toBeInTheDocument();
      // The virtualizer always renders an inner container div even when empty
      expect(log.children.length).toBe(1);
    });
  });

  describe('structure and order', () => {
    it('renders cells in the same order as the agents prop', () => {
      const agents = [
        createAgent({ agentId: 'first', profile: 'First' }),
        createAgent({ agentId: 'second', profile: 'Second' }),
        createAgent({ agentId: 'third', profile: 'Third' }),
      ];
      const { container } = render(<AgentGrid agents={agents} />);
      const cells = container.querySelectorAll('.agent-cell');
      expect(cells[0]).toHaveTextContent('First');
      expect(cells[1]).toHaveTextContent('Second');
      expect(cells[2]).toHaveTextContent('Third');
    });

    it('each cell contains a header and a body', () => {
      const agents = [createAgent()];
      const { container } = render(<AgentGrid agents={agents} />);
